import{_ as o}from"./chunks/analytics_spotify.Vl1ZPEQh.js";import{_ as a}from"./chunks/analytics_spotify_discovery.CA1B06lf.js";import{_ as n,H as r,c as i,b as p,a0 as s,K as d}from"./chunks/framework.DZ_FiXNr.js";const l="/images/analytics_spotify_episodes.webp",c="/images/analytics_spotify_audience.webp",S=JSON.parse(`{"title":"Spotify analytics","description":"Spotify analytics connects discovery with listening: how often your show is seen, which episodes get plays, who returns, and how listeners move through an episode. Keep Spotify's own measurements and date windows separate from host downloads and Apple listening.","frontmatter":{},"headers":[],"relativePath":"features/spotify-analytics.md","filePath":"features/spotify-analytics.md"}`),h={name:"features/spotify-analytics.md"};function g(y,e,m,u,f,w){const t=r("HelpWalkthrough");return p(),i("div",null,[e[0]||(e[0]=s('<h1 id="spotify-analytics" tabindex="-1">Spotify analytics <a class="header-anchor" href="#spotify-analytics" aria-label="Permalink to &quot;Spotify analytics&quot;">​</a></h1><p>Spotify analytics connects discovery with listening: how often your show is seen, which episodes get plays, who returns, and how listeners move through an episode. Keep Spotify&#39;s own measurements and date windows separate from host downloads and Apple listening.</p><p><strong>To access:</strong> choose your podcast → <strong>Analytics → Spotify</strong>. Follow <a href="/features/analytics-connections.html#spotify-for-creators">Connect Spotify</a> if reports are not connected yet.</p><p><a href="/images/analytics_spotify.webp" title="Open screenshot at full size"><img src="'+o+'" alt="Spotify overview with the available report views"></a></p><h2 id="start-with-overview" tabindex="-1">Start with Overview <a class="header-anchor" href="#start-with-overview" aria-label="Permalink to &quot;Start with Overview&quot;">​</a></h2><p>The <strong>30</strong>, <strong>90</strong> and <strong>365 days</strong> selector changes the plays period. The daily chart, daily average and best day help you spot changes within it. <strong>Unique listeners, last 30 days</strong> and <strong>Listening &amp; audience</strong> retain their own dates: follower growth, listening hours, new listeners and returning listeners may have different windows.</p><p>When Spotify hosts your show, additional <strong>On Spotify</strong> and <strong>Everywhere else</strong> measurements can appear. Someone who listens in both places may appear in both listener counts. Do not add those counts to estimate unique people.</p><p>In historical reports such as <strong>Listening &amp; engagement</strong>, select the metric you want, open <strong>Reported values</strong>, or choose <strong>Export CSV</strong>. <strong>Who comes back</strong> is weekly audience retention across the show; it is not the completion rate of one episode.</p><h2 id="find-and-compare-episodes" tabindex="-1">Find and compare episodes <a class="header-anchor" href="#find-and-compare-episodes" aria-label="Permalink to &quot;Find and compare episodes&quot;">​</a></h2><p>Open <strong>Episodes</strong>, enter part of a title in <strong>Find an episode…</strong>, choose a sort order, then click <strong>Apply</strong>. Sort options include impressions, plays, newest first, completion and title. Use the page controls for more episodes.</p><p><a href="/images/analytics_spotify_episodes.webp" title="Open screenshot at full size"><img src="'+l+'" alt="Spotify episode search, sort and performance columns"></a></p><p>The table&#39;s impressions, <strong>From Search</strong> and plays describe the latest reported 30-day snapshot. <strong>First 7 days</strong> and <strong>First 30 days</strong> describe each episode&#39;s launch. They are different windows; check progress labels before comparing a new episode with a completed launch.</p><p>Completion is Spotify&#39;s reported completion measurement, not a value calculated by dividing the plays and impressions shown beside it.</p><h2 id="explore-an-episode-in-detail" tabindex="-1">Explore an episode in detail <a class="header-anchor" href="#explore-an-episode-in-detail" aria-label="Permalink to &quot;Explore an episode in detail&quot;">​</a></h2><p>Click its title to open the report underneath the row. Depending on what Spotify supplies, it can include:</p><ul><li><strong>Listening retention</strong> along the episode, with listening milestones where available.</li><li><strong>The first 30 days</strong>, showing the available launch-day history.</li><li><strong>Performance by window</strong>, with a metric selector for plays, listeners, impressions, hours, completion or other reported measures. Each window is independent.</li><li><strong>Launch totals &amp; discovery sources</strong>, with Search, Home, Library and Other where reported.</li><li><strong>This episode&#39;s audience</strong>, plus expandable audience breakdowns.</li><li><strong>How Spotify describes this episode</strong>, containing reported topics, transcript keywords, guests and chapters.</li></ul>',16)),d(t,{src:"/walkthroughs/spotify-episode.webp",poster:"/images/analytics_spotify_episode_detail.webp",alt:"Open a Spotify episode and explore its listening report",duration:20200}),e[1]||(e[1]=s('<p>Missing reports remain explicitly unavailable; not every episode has every breakdown. <strong>Reported values</strong> exposes the exact measurements and <strong>Export CSV</strong> exports that report. Do not add unique listeners across launch windows or daily snapshots.</p><p>Choose <strong>Find this episode across your connected platforms</strong> to compare listening curves with Apple or read the other sources&#39; episode measurements. <a href="/features/analytics.html#compare-listening-curves-and-select-a-passage">Analytics</a> explains the shared timeline and interval controls.</p><h2 id="read-audience-and-discovery" tabindex="-1">Read Audience and Discovery <a class="header-anchor" href="#read-audience-and-discovery" aria-label="Permalink to &quot;Read Audience and Discovery&quot;">​</a></h2><p><strong>Audience</strong> includes country maps, age/gender, apps and devices where reported. Expand <strong>Regions and cities</strong> for more detail. Where a country map is available, expand <strong>All reported countries</strong> and select a country to highlight it and read its reported share. Each dimension keeps its own date and window; a list can cover only the locations Spotify reports.</p><p><a href="/images/analytics_spotify_audience.webp" title="Open screenshot at full size"><img src="'+c+'" alt="Spotify audience geography and demographics"></a></p><p><strong>Discovery</strong> shows impressions and sources such as Search, Home and Library, plus the available impression-to-play funnel and history. An impression means Spotify showed your show; it is not an audio play or a unique listener. Funnel steps keep their own dates, so do not derive a new conversion rate from unrelated windows.</p><p><a href="/images/analytics_spotify_discovery.webp" title="Open screenshot at full size"><img src="'+a+'" alt="Spotify discovery sources, search impressions and funnel"></a></p><p>Spotify&#39;s <strong>Search</strong> bucket can include charts and editorial recommendations. It is not a list of exact search queries. Episode topics and transcript keywords describe content; they do not prove which words a listener typed. Use <a href="/features/keyword-strategy.html">Strategy</a> and <a href="/features/rankings.html">Rankings</a> for your tracked search work.</p><h2 id="benchmarks-and-partner-program" tabindex="-1">Benchmarks and Partner Program <a class="header-anchor" href="#benchmarks-and-partner-program" aria-label="Permalink to &quot;Benchmarks and Partner Program&quot;">​</a></h2><p><strong>Benchmarks</strong> shows Spotify&#39;s comparable-show percentiles where available. These describe the comparison group, not your own score. Expand a benchmark to inspect the chart and its reported values. <strong>All reported show measurements</strong> lists observations with their windows and read dates; different windows are separate measurements.</p><p><strong>Partner Program</strong> shows Spotify&#39;s reported progress toward its application thresholds and links to its current criteria. Reaching the displayed thresholds allows an application; it does not guarantee acceptance. Read the hosting and country notes and check the program in Spotify for Creators.</p><h2 id="when-a-report-looks-incomplete" tabindex="-1">When a report looks incomplete <a class="header-anchor" href="#when-a-report-looks-incomplete" aria-label="Permalink to &quot;When a report looks incomplete&quot;">​</a></h2><p>Check the connection state and each report&#39;s date first. Connected does not mean every report is already available. A missing value is not zero, and a retained snapshot is not a new measurement. Use <a href="/features/connections.html">Connections</a> for access changes and <a href="/features/analytics-connections.html">Analytics Connections</a> for setup or reconnection. Why these reports need a show claimed in Spotify for Creators: <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><p>For a regular review, compare an episode&#39;s discovery, plays and listening curve using the labelled windows. Treat a change after a new title or release as a lead to investigate, not proof of cause.</p>',14))])}const k=n(h,[["render",g]]);export{S as __pageData,k as default};
